/**
 * Cloudflare Worker entry point (wrangler.jsonc "main").
 *
 * OpenNext builds the Next.js app into .open-next/worker.js, which only handles HTTP requests.
 * This wrapper adds:
 *  - scheduled(): the Cron Trigger in wrangler.jsonc calls the app's own /api/cron route, which
 *    does what the long-running Node scheduler does locally (poll IESO, fill the backfill).
 *  - Hyperdrive: when a HYPERDRIVE binding exists its connection string is handed to the app
 *    (src/lib/db.ts reads HYPERDRIVE_DATABASE_URL before DATABASE_URL).
 */

// @ts-ignore: .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import { default as handler } from "../.open-next/worker.js";

interface Env {
  HYPERDRIVE?: { connectionString: string };
  CRON_SECRET?: string;
  [key: string]: unknown;
}

interface Ctx {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException(): void;
}

function applyBindings(env: Env) {
  if (env.HYPERDRIVE?.connectionString) process.env.HYPERDRIVE_DATABASE_URL = env.HYPERDRIVE.connectionString;
}

export default {
  async fetch(request: Request, env: Env, ctx: Ctx): Promise<Response> {
    applyBindings(env);
    return handler.fetch(request, env, ctx);
  },

  async scheduled(_controller: unknown, env: Env, ctx: Ctx): Promise<void> {
    applyBindings(env);
    const headers = new Headers();
    if (env.CRON_SECRET) headers.set("authorization", `Bearer ${env.CRON_SECRET}`);
    const res: Response = await handler.fetch(new Request("https://localhost/api/cron", { headers }), env, ctx);
    const body = await res.text();
    if (!res.ok) throw new Error(`/api/cron returned HTTP ${res.status}: ${body.slice(0, 500)}`);
    console.log(`[cron] ${body.slice(0, 500)}`);
  },
};
